"""
apply_day10.py  -  ONE FILE that upgrades your production-rag project to Day 10.

HOW TO USE (Windows CMD), from inside your production-rag folder:
    .venv\\Scripts\\activate
    python apply_day10.py

What it does:
  1. Backs up every file it is about to change into  _backup_before_day10\\
  2. Writes all Day 1-10 code, tests, scripts, evals and docs into this folder
  3. NEVER touches: .env, .venv, app\\storage, evals\\reports
     (your tenants.db, if you already made one, lives under app\\storage and is preserved)
  4. Runs  pip install -r requirements.txt
  5. Runs  python scripts\\verify_day10.py  (tests + a real two-tenant isolation check)

IMPORTANT: Day 10 requires an API key on every /documents, /search, /ask call.
On first server startup with no keys yet, one is auto-created and printed to
the console ONCE. Save it, or create your own right away:
    python scripts\\manage_keys.py create --tenant you --label "my key"

Options:
    --no-install    skip pip install
    --no-verify     skip the verification run
    --offline       verification without a live call (free either way for Day 10)
    --force         run even if this does not look like a production-rag folder
"""

